#!/usr/bin/env bash
# Renders BENCHMARKS.md from the raw benchmark outputs in /tmp/bench/.
# Called by .github/workflows/benchmark.yml after the suite runs.
set -euo pipefail

RUNTIME=/tmp/bench/runtime.txt
TUNING=/tmp/bench/tuning.txt
WORKLOAD=/tmp/bench/workload.txt
OUT=BENCHMARKS.md

DATE="${RUN_DATE:-$(date -u +%Y-%m-%dT%H:%M:%SZ)}"
SHORT_SHA="${COMMIT_SHA:0:7}"

headline() {
  # Pull the key metric bullet lines out of every benchmark log.
  grep -h "• Raw Worker IPC Round-Trip\|• End-to-End Runtime Task Cost\|• Scheduler + Graph Overhead\|• Worker Fleet Event Loop Lag\|• RSS Heap Memory\|• V8/JSC Heap Used\|• 25,000 Tasks Completed in\|• Peak RSS Memory\|• Settled Cooldown RSS" \
    "$RUNTIME" "$TUNING" "$WORKLOAD" 2>/dev/null | sort -u || true
}

md_table() {
  # Extract markdown table rows (already emitted by the benchmarks).
  grep -h "^|" "$1" 2>/dev/null || true
}

details() {
  local title="$1" file="$2"
  {
    echo "<details>"
    echo "<summary>$title (full log)</summary>"
    echo ""
    echo '```'
    cat "$file" 2>/dev/null || echo "(log unavailable)"
    echo '```'
    echo "</details>"
  }
}

{
  echo "# Yatta Benchmarks"
  echo ""
  echo "> Last run: \`$DATE\` · commit [\`$SHORT_SHA\`](https://github.com/psrockstar098/yatta.js/commit/$COMMIT_SHA) · \`ubuntu-latest\`, Bun 1.4.2"
  echo ">"
  echo "> Benchmarks run on every push to \`main\` and weekly via GitHub Actions."
  echo "> Numbers come from shared CI runners, so treat them as relative — the trend matters more than any single value."
  echo ""
  echo "## Headline metrics"
  echo ""
  echo '```'
  METRICS="$(headline)"
  if [ -n "$METRICS" ]; then
    echo "$METRICS"
  else
    echo "(benchmark output unavailable — see workflow logs)"
  fi
  echo '```'
  echo ""
  echo "## Throughput ladder (worker runtime)"
  echo ""
  echo "Fast-ping tasks through the worker fleet, 10 → 10,000 concurrent:"
  echo ""
  TABLES="$(md_table "$RUNTIME" | head -10)"
  if [ -n "$TABLES" ]; then echo "$TABLES"; else echo "_No table data captured._"; fi
  echo ""
  echo "## Real-world workloads"
  echo ""
  echo "JSON payload transformation and micro-compute tasks:"
  echo ""
  TABLES="$(md_table "$WORKLOAD" | head -30)"
  if [ -n "$TABLES" ]; then echo "$TABLES"; else echo "_No table data captured._"; fi
  echo ""
  echo "## Full logs"
  echo ""
  details "Worker runtime deep profile" "$RUNTIME"
  echo ""
  details "Topology & tail tuning" "$TUNING"
  echo ""
  details "Comprehensive workload benchmark" "$WORKLOAD"
  echo ""
  echo "---"
  echo "_Generated by [\`benchmark.yml\`](.github/workflows/benchmark.yml)._"
} > "$OUT"

echo "Wrote $OUT"
